        return r;
    }

    // Parse .gitconfig format:
    // - [section] -> keys as "section.key". [section "subsection"] -> "section.subsection.key".
    // - '#' and ';' comments outside double quotes. Quoted values unquoted.
    // - Lines ending '\' continue (leading space trimmed). Keys lowercased.
    static Dictionary<string, string> ParseGitConfig(string text)
