using System;
using System.Collections.Generic;

class Program
{
    static string StripComment(string s)
    {
        bool inQ = false;
        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == '"') inQ = !inQ;
            if (!inQ && (s[i] == '#' || s[i] == ';')) return s.Substring(0, i);
        }
        return s;
    }

    static string Unquote(string s)
    {
        s = s.Trim();
        if (s.Length >= 2 && s[0] == '"' && s[s.Length - 1] == '"')
            return s.Substring(1, s.Length - 2);
        return s;
    }

    // Parse INI-style config:
    // - [section] prefixes following keys as section.key
    // - lines ending with backslash continue on the next physical line
    //   (leading whitespace of continuation is trimmed)
    // - # and ; start comments (outside quotes)
    // - keys use '=' or ':' as separator
    static Dictionary<string, string> ParseConfig(string text)
    {
        var result = new Dictionary<string, string>();
        string section = "", pending = "";
        foreach (string raw in text.Split('\n'))
        {
            string line = pending.Length > 0 ? raw.TrimStart() : raw;
            if (line.EndsWith("\\"))
            { pending += line.Substring(0, line.Length - 1); continue; }
            pending += line;
