int sep = logical.IndexOfAny(new[] { '=', ':' });
if (sep < 0) continue;
string key = logical.Substring(0, sep).Trim();
string val = Unquote(logical.Substring(sep + 1));
string fk = section.Length > 0 ? section + "." + key : key;
result[fk] = val;

suffix:
        }
        return result;
    }

    static void Main(string[] args)
    {
        string cfg = "name = Alice\n" +
                     "path = /usr/\\\n" +
                     "  local/bin\n" +
                     "note = \"keep # sign\" # tail\n" +
                     "; skip me\n" +
                     "[db]\n" +
                     "host : localhost";
        var m = ParseConfig(cfg);
        if (m["name"] != "Alice") throw new Exception("name");
        if (m["path"] != "/usr/local/bin") throw new Exception("path");
        if (m["note"] != "keep # sign") throw new Exception("note");
        if (m.ContainsKey("; skip me")) throw new Exception("comment parsed");
        if (m["db.host"] != "localhost") throw new Exception("section key");
