using System.Collections.Generic;

class Program
{
    // Parses INI-style config. Rules:
    // - Lines starting with # or ; are comments (but only if # or ; is the FIRST non-space char)
    // - [section] starts a new section
    // - key = value pairs; value is trimmed
    // - A line ending with \ continues on the next line (strip the \, join, trim result)
    // - Duplicate keys within a section: values are joined with comma
    // - Returns Dict<string, Dict<string, string>>
    static Dictionary<string, Dictionary<string, string>> ParseIni(string text)
    {

golden_completion:
