using System;

class Program
{
    // Edit distance with custom costs:
    // - Insert cost: 1
    // - Delete cost: 1
    // - Substitution cost: 2 (NOT the standard 1!)
    // - Transposition of adjacent chars cost: 0.5
    // Returns minimum cost as double.
    static double EditDistance(string a, string b)
    {

