for (int i = 1; i <= m; i++)
    for (int j = 1; j <= n; j++)
    {
        double cost = a[i - 1] == b[j - 1] ? 0 : 2;
        dp[i, j] = Math.Min(Math.Min(dp[i - 1, j] + 1, dp[i, j - 1] + 1), dp[i - 1, j - 1] + cost);
        if (i > 1 && j > 1 && a[i - 1] == b[j - 2] && a[i - 2] == b[j - 1])
            dp[i, j] = Math.Min(dp[i, j], dp[i - 2, j - 2] + 0.5);
    }
