class Program
{
    // Parse markdown table into list of dictionaries.
    // Rules:
    // - First row is header
    // - Second row is separator (---) — skip it
    // - Remaining rows are data
    // - Cells are separated by | and trimmed
    // - Leading/trailing | on each row are stripped before splitting
    // - Pipes inside backtick-quoted spans (`code|here`) are NOT delimiters
    // Returns List<Dict<string,string>> where keys are header names
    static List<Dictionary<string, string>> ParseMarkdownTable(string text)
    {

