using System;
using System.Collections.Generic;

class Program
{
    // Split identifier into words. Custom rules:
    // - Split before uppercase letter that follows a lowercase letter: "fooBar" -> ["foo","Bar"]
    // - Split before uppercase letter that is followed by lowercase (in an acronym run): "XMLParser" -> ["XML","Parser"]
    // - Underscores are delimiters (removed from output)
    // - Transition from letter to digit starts a new word: "abc123" -> ["abc","123"]
    // - Transition from digit to uppercase starts a new word: "123ABC" -> ["123","ABC"]
    // - Digit followed by lowercase stays in same word: "get2x" -> ["get","2x"]
    // - Return words in their original case (no lowering)
    static List<string> SplitIdentifier(string input)
    {

