        if (i > start) words.Add(input.Substring(start, i - start));
        start = i + 1;
        continue;
    }
    if (i > start)
    {
        bool prevLower = char.IsLower(input[i - 1]);
        bool curUpper = char.IsUpper(input[i]);
        bool prevDigit = char.IsDigit(input[i - 1]);
        bool curDigit = char.IsDigit(input[i]);
        bool prevUpper = char.IsUpper(input[i - 1]);
        bool curLower = char.IsLower(input[i]);
        bool split = false;
        // lowercase -> uppercase: "fooBar"
        if (prevLower && curUpper) split = true;
        // letter -> digit: "abc123"
        if (!prevDigit && !input[i-1].Equals('_') && curDigit) split = true;
        // digit -> uppercase: "2X" splits, but "2nd" does NOT
        if (prevDigit && curUpper) split = true;
        // acronym boundary: "XMLParser" -> "XML","Parser"
        if (curUpper && i + 1 < input.Length && char.IsLower(input[i + 1]) && i > start && prevUpper)
            split = true;
        if (split)
        {
            words.Add(input.Substring(start, i - start));
            start = i;
        }
    }
}
if (start < input.Length) words.Add(input.Substring(start));
