using System.Collections.Generic;

class Program
{
    // Split a command line string into arguments, shell-style:
    // - Spaces delimit arguments
    // - Double-quoted strings: spaces preserved, \" for literal quote, \\ for literal backslash
    // - Single-quoted strings: everything literal (no escapes), ended by next '
    // - Unquoted backslash escapes the next character
    // - Adjacent quoted/unquoted segments join into one argument: he"ll"o -> hello
    static List<string> ShellSplit(string input)
    {

