    if (c == '"')
    {
        hasArg = true; i++;
        while (i < input.Length && input[i] != '"')
        {
            if (input[i] == '\\' && i + 1 < input.Length && (input[i + 1] == '"' || input[i + 1] == '\\'))
            { current.Append(input[i + 1]); i += 2; }
            else { current.Append(input[i]); i++; }
        }
        if (i < input.Length) i++; // skip closing "
    }
    else if (c == '\'')
    {
        hasArg = true; i++;
        while (i < input.Length && input[i] != '\'')
        { current.Append(input[i]); i++; }
        if (i < input.Length) i++; // skip closing '
    }
    else if (c == '\\' && i + 1 < input.Length)
    {
