    {
        var r1 = ShellSplit("echo hello world");
        if (r1.Count != 3 || r1[0] != "echo") throw new Exception($"Simple: {string.Join("|", r1)}");

        var r2 = ShellSplit("echo \"hello world\"");
        if (r2.Count != 2 || r2[1] != "hello world") throw new Exception($"Dquote: {string.Join("|", r2)}");

        var r3 = ShellSplit("echo 'hello world'");
