using System;
using System.Collections.Generic;

class Program
{
    // Match a URL path against a route pattern and extract parameters.
    // Pattern syntax:
    //   /literal — exact match
    //   /{name} — captures any non-slash segment into params["name"]
    //   /{name:int} — captures only if segment is all digits
    //   /{*rest} — captures everything remaining (including slashes), must be last
    // Returns null if no match, otherwise Dictionary<string,string> of captured params.
    static Dictionary<string, string> MatchRoute(string pattern, string path)
    {

golden_completion:
var result = new Dictionary<string, string>();
string[] patParts = pattern.Split(new[]{'/'},  StringSplitOptions.RemoveEmptyEntries);
string[] pathParts = path.Split(new[]{'/'}, StringSplitOptions.RemoveEmptyEntries);
int pi = 0;
for (int i = 0; i < patParts.Length; i++)
{
    string seg = patParts[i];
    if (seg.StartsWith("{*") && seg.EndsWith("}"))
    {
        string name = seg.Substring(2, seg.Length - 3);
        result[name] = string.Join("/", pathParts, pi, pathParts.Length - pi);
        return result;
    }
    if (pi >= pathParts.Length) return null;
    if (seg.StartsWith("{") && seg.EndsWith("}"))
    {
        string inner = seg.Substring(1, seg.Length - 2);
        int colon = inner.IndexOf(':');
        string name = colon >= 0 ? inner.Substring(0, colon) : inner;
        string constraint = colon >= 0 ? inner.Substring(colon + 1) : null;
        if (constraint == "int")
            foreach (char c in pathParts[pi]) if (!char.IsDigit(c)) return null;
        result[name] = pathParts[pi];
        pi++;
    }
    else
    {
        if (pathParts[pi] != seg) return null;
        pi++;
    }
}
if (pi != pathParts.Length) return null;
return result;

suffix:
    }

    static void Main()
    {
        var r1 = MatchRoute("/users/{id}", "/users/42");
        if (r1 == null || r1["id"] != "42") throw new Exception("Simple param failed");

        var r2 = MatchRoute("/users/{id:int}", "/users/abc");
        if (r2 != null) throw new Exception("Int constraint should reject abc");

        var r3 = MatchRoute("/files/{*path}", "/files/a/b/c");
        if (r3 == null || r3["path"] != "a/b/c") throw new Exception($"Wildcard: got {r3?["path"]}");

        var r4 = MatchRoute("/api/v1", "/api/v2");
        if (r4 != null) throw new Exception("Literal mismatch should fail");

        Console.WriteLine("Visible checks passed.");
    }
}

