static List<object> Tokenize(string expr, Dictionary<string, int> vars)
{
    var tokens = new List<object>();
    int pos = 0;
    while (pos < expr.Length)
    {
        if (char.IsWhiteSpace(expr[pos])) { pos++; continue; }
        if (char.IsDigit(expr[pos]))
        {
            int start = pos;
            while (pos < expr.Length && char.IsDigit(expr[pos])) pos++;
            tokens.Add(int.Parse(expr.Substring(start, pos - start)));
            continue;
        }
        if (char.IsLetter(expr[pos]))
        {
            int start = pos;
            while (pos < expr.Length && char.IsLetterOrDigit(expr[pos])) pos++;
            string varName = expr.Substring(start, pos - start);
            if (!vars.TryGetValue(varName, out int value)) throw new Exception($"Undefined variable: {varName}");
            tokens.Add(value);
            continue;
        }
        char c = expr[pos++];
        switch (c)
        {
            case '+': tokens.Add('+'); break;
            case '-': tokens.Add('-'); break;
            case '*': tokens.Add('*'); break;
            case '/': tokens.Add('/'); break;
            case '(': tokens.Add('('); break;
            case ')': tokens.Add(')'); break;
            default: throw new Exception($"Invalid character: {c}");
        }
    }
    return tokens;
}

