    // Sort strings using custom rules (NOT standard lexicographic!):
    // 1. Shorter strings come first
    // 2. Same length: sort by vowel count (more vowels first)
    // 3. Same length and vowel count: sort lexicographically (case-insensitive)
    // Vowels are: a, e, i, o, u (case-insensitive)
    static List<string> CustomSort(List<string> items)
    {

